// ===== CONFIGURA AQUÍ =====
// KEYWORDS: lo que buscarías en Google Maps (tu cliente ideal).
// ZONAS: centro (lat, lng) y radio en km de cada zona. Ordénalas de más cerca a más lejos.
// Cada ejecución hace unas pocas búsquedas y avanza un cursor para no repetirlas.
const KEYWORDS = [
  'empresa forestal', 'trabajos forestales', 'servicios forestales', 'vivero forestal',
  'ingeniería forestal', 'consultora medio ambiente', 'prevención incendios forestales',
  'desbroces y podas', 'educación ambiental', 'turismo de naturaleza'
];
const ZONAS = [
  // Anillo 1 (0-20 km)
  { nombre: 'València ciudad', lat: 39.4699, lng: -0.3763, r: 7 },
  { nombre: "L'Horta Nord", lat: 39.555, lng: -0.390, r: 8 },
  { nombre: "L'Horta Oest", lat: 39.490, lng: -0.470, r: 8 },
  { nombre: "L'Horta Sud", lat: 39.410, lng: -0.440, r: 8 },
  // Anillo 2 (20-50 km)
  { nombre: 'Camp de Morvedre', lat: 39.680, lng: -0.290, r: 10 },
  { nombre: 'Camp de Túria', lat: 39.620, lng: -0.600, r: 12 },
  { nombre: 'Ribera Baixa', lat: 39.200, lng: -0.320, r: 10 },
  { nombre: 'Hoya de Buñol', lat: 39.430, lng: -0.800, r: 12 },
  { nombre: 'Ribera Alta', lat: 39.140, lng: -0.480, r: 12 },
  // Anillo 3 (> 50 km)
  { nombre: 'Los Serranos', lat: 39.760, lng: -0.950, r: 18 },
  { nombre: 'La Costera', lat: 38.990, lng: -0.560, r: 12 },
  { nombre: 'La Safor', lat: 38.970, lng: -0.230, r: 12 },
  { nombre: 'Canal de Navarrés', lat: 39.080, lng: -0.730, r: 12 },
  { nombre: 'Requena-Utiel', lat: 39.500, lng: -1.150, r: 20 },
  { nombre: "Vall d'Albaida", lat: 38.840, lng: -0.520, r: 12 },
  { nombre: 'Valle de Cofrentes-Ayora', lat: 39.120, lng: -1.050, r: 20 },
  { nombre: 'Rincón de Ademuz', lat: 40.060, lng: -1.280, r: 12 },
];
const BUSQUEDAS_POR_EJECUCION = 4; // Text Search: tope 150/día en Google Cloud

const state = $getWorkflowStaticData('global');
const total = KEYWORDS.length * ZONAS.length;
const cursor = (state.cursor || 0) % total;

const out = [];
for (let i = 0; i < BUSQUEDAS_POR_EJECUCION; i++) {
  const idx = (cursor + i) % total;
  const zona = ZONAS[Math.floor(idx / KEYWORDS.length)];
  const keyword = KEYWORDS[idx % KEYWORDS.length];
  const dLat = zona.r / 111;
  const dLng = zona.r / (111 * Math.cos(zona.lat * Math.PI / 180));
  out.push({ json: {
    keyword, zona: zona.nombre, posicion: `${idx + 1}/${total}`,
    body: {
      textQuery: keyword, languageCode: 'es', regionCode: 'ES', pageSize: 20,
      locationRestriction: { rectangle: {
        low: { latitude: zona.lat - dLat, longitude: zona.lng - dLng },
        high: { latitude: zona.lat + dLat, longitude: zona.lng + dLng },
      } },
    },
  } });
}
state.cursor = (cursor + BUSQUEDAS_POR_EJECUCION) % total;
return out;

// Junta los resultados, quita repetidos y deja solo empresas abiertas de tu provincia
// ===== CONFIGURA AQUÍ =====
const CASA = { lat: 39.4699, lng: -0.3763 }; // Tu punto de partida (oficina). Ejemplo: centro de València
const PREFIJO_CP = '46';                     // Código postal de tu provincia (46 = Valencia, 28 = Madrid, 08 = Barcelona…)
const PROVINCIA = 'Valencia';
const distanciaKm = (lat, lng) => {
  const rad = x => x * Math.PI / 180, R = 6371;
  const dLat = rad(lat - CASA.lat), dLng = rad(lng - CASA.lng);
  const a = Math.sin(dLat / 2) ** 2 + Math.cos(rad(CASA.lat)) * Math.cos(rad(lat)) * Math.sin(dLng / 2) ** 2;
  return Math.round(2 * R * Math.asin(Math.sqrt(a)) * 10) / 10;
};
const TIPOS_DESCARTADOS = ['restaurant', 'bar', 'cafe', 'supermarket', 'grocery_store', 'car_dealer', 'car_repair', 'gas_station', 'clothing_store'];

const busquedas = $('Elegir búsquedas de hoy').all();
const empresas = new Map();
$input.all().forEach((item, i) => {
  const q = (busquedas[i] || {}).json || {};
  for (const p of item.json.places || []) {
    if (!p.id || empresas.has(p.id)) continue;
    const comp = p.addressComponents || [];
    const get = t => (comp.find(c => (c.types || []).includes(t)) || {}).longText || '';
    if (!get('postal_code').startsWith(PREFIJO_CP)) continue;
    if (p.businessStatus && p.businessStatus !== 'OPERATIONAL') continue;
    if ((p.types || []).some(t => TIPOS_DESCARTADOS.includes(t))) continue;
    empresas.set(p.id, {
      placeId: p.id,
      nombre: (p.displayName || {}).text || '',
      direccion: p.formattedAddress || '',
      municipio: get('locality') || get('administrative_area_level_3'),
      provincia: PROVINCIA,
      distanciaKm: p.location ? distanciaKm(p.location.latitude, p.location.longitude) : null,
      googleMaps: p.googleMapsUri || null,
      tipos: p.types || [],
      keyword: q.keyword, zona: q.zona,
    });
  }
});
return [...empresas.values()].map(json => ({ json }));

// Quita las empresas que ya están en Airtable y se queda con las más cercanas
const MAX_EMPRESAS = 10; // Place Details: tope 30/día en Google Cloud
const existentes = new Set($input.all()
  .map(i => i.json['Google Place ID'] || (i.json.fields || {})['Google Place ID'])
  .filter(Boolean));
return $('Unir y filtrar (provincia de Valencia)').all()
  .map(i => i.json)
  .filter(e => !existentes.has(e.placeId))
  .sort((a, b) => (a.distanciaKm ?? 999) - (b.distanciaKm ?? 999))
  .slice(0, MAX_EMPRESAS)
  .map(json => ({ json }));

// Visita la web de cada empresa (inicio + /contacto) y saca email, redes sociales y descripción
const empresas = $('Quitar duplicados y limitar').all();
const detalles = $input.all();

const decode = s => s.replace(/&amp;/g, '&').replace(/&quot;/g, '"').replace(/&#39;|&#039;/g, "'")
  .replace(/&aacute;/g, 'á').replace(/&eacute;/g, 'é').replace(/&iacute;/g, 'í').replace(/&oacute;/g, 'ó')
  .replace(/&uacute;/g, 'ú').replace(/&ntilde;/g, 'ñ').replace(/\s+/g, ' ').trim();
const primero = (html, re, malos) => {
  for (const m of html.matchAll(re)) {
    const id = m[m.length - 1];
    if (!malos.includes(id.toLowerCase())) return m[0];
  }
  return null;
};

const out = [];
for (let i = 0; i < empresas.length; i++) {
  const d = (detalles[i] || {}).json || {};
  const e = {
    ...empresas[i].json,
    web: d.websiteUri || null,
    telefono: d.internationalPhoneNumber || d.nationalPhoneNumber || null,
    rating: d.rating ?? null,
    resenas: d.userRatingCount ?? null,
    email: null, instagram: null, facebook: null, linkedin: null, descripcion: null,
  };

  let html = '';
  if (e.web) {
    for (const ruta of ['', '/contacto']) {
      try {
        const url = ruta ? new URL(ruta, e.web).href : e.web;
        const r = await this.helpers.httpRequest({ url, timeout: 10000, json: false, skipSslCertificateValidation: true });
        html += ' ' + String(r).slice(0, 500000);
      } catch (err) { /* web caída o sin /contacto */ }
    }
  }

  if (html) {
    const dominio = (() => { try { return new URL(e.web).hostname.replace(/^www\./, ''); } catch { return ''; } })();
    const emails = [...new Set((html.match(/[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}/g) || [])
      .map(x => x.toLowerCase())
      .filter(x => !/\.(png|jpe?g|gif|svg|webp)$/.test(x) && !/(sentry|wixpress|example|domain\.com|u003e)/.test(x)))];
    // Solo emails fiables: del dominio de la web, enlazados con mailto: o de proveedores habituales
    // (evita el email del diseñador de la web o restos de plantillas)
    const mailtos = new Set([...html.matchAll(/mailto:([^"'?\s>]+)/gi)].map(m => decodeURIComponent(m[1]).toLowerCase()));
    const esDelDominio = x => dominio && (x.endsWith('@' + dominio) || x.endsWith('.' + dominio));
    const esProveedor = x => /@(gmail|hotmail|outlook|yahoo|icloud|live|telefonica|ono)\./.test(x);
    e.email = emails.find(esDelDominio) || emails.find(x => mailtos.has(x)) || emails.find(esProveedor) || null;

    const ig = primero(html, /https?:\/\/(?:www\.)?instagram\.com\/([A-Za-z0-9_.]{2,30})/g, ['p', 'reel', 'explore', 'accounts', 'sharer', 'share']);
    if (ig) e.instagram = ig.replace(/^http:/, 'https:');
    const fb = primero(html, /https?:\/\/(?:www\.)?facebook\.com\/([A-Za-z0-9_.\-]{2,80})/g, ['sharer', 'sharer.php', 'share', 'plugins', 'tr', 'dialog', 'login']);
    if (fb) e.facebook = fb.replace(/^http:/, 'https:');
    const li = primero(html, /https?:\/\/(?:[a-z]{2,3}\.)?linkedin\.com\/(?:company|in|school)\/([A-Za-z0-9_\-%.]+)/g, ['sharearticle']);
    if (li) e.linkedin = li.replace(/^http:/, 'https:');

    const meta = html.match(/<meta[^>]+(?:name|property)=["'](?:description|og:description)["'][^>]*content=["']([^"']{20,})["']/i)
      || html.match(/<meta[^>]+content=["']([^"']{20,})["'][^>]*(?:name|property)=["'](?:description|og:description)["']/i);
    if (meta) e.descripcion = decode(meta[1]).slice(0, 1000);
  }
  out.push({ json: e });
}
return out;

// Clasifica la actividad y monta la ficha con los nombres exactos de los campos de Airtable
// ===== CONFIGURA AQUÍ ===== Cambia las REGLAS por las actividades de tu sector.
const norm = s => (s || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '');
const REGLAS = [
  ['Vivero forestal', /vivero/],
  ['Prevención de incendios', /incendi|cortafuego|bomber/],
  ['Educación ambiental', /educacion ambiental|granja escuela|aula de (la )?naturaleza/],
  ['Turismo de naturaleza', /turismo|aventura|senderismo|excursion|ecoturismo/],
  ['Aprovechamiento maderero', /maderer|aserr|biomasa|lena\b|madera/],
  ['Trabajos forestales', /desbroce|poda|tala|trabajos forestales|servicios forestales|silvicult|repobla|clareo/],
  ['Consultora / ingeniería ambiental', /consultor|ingenier|medio ?ambient|ambiental/],
  ['Espacios naturales / restauración', /restauracion|espacios naturales|paisaj|bioingenier/],
  ['Gestión forestal', /forestal|montes/],
];
const hoy = new Date().toLocaleDateString('en-CA', { timeZone: 'Europe/Madrid' });

return $input.all().map(({ json: e }) => {
  const texto = norm([e.nombre, e.descripcion, e.keyword].join(' '));
  const actividad = (REGLAS.find(([, re]) => re.test(texto)) || ['Otro naturaleza'])[0];
  const fields = {
    'Nombre': e.nombre,
    'Actividad': actividad,
    'Descripción': e.descripcion,
    'Teléfono': e.telefono,
    'Email': e.email,
    'Página web': e.web,
    'Instagram': e.instagram,
    'LinkedIn': e.linkedin,
    'Facebook': e.facebook,
    'Dirección': e.direccion,
    'Municipio': e.municipio,
    'Provincia': e.provincia,
    'Google Maps': e.googleMaps,
    'Google Place ID': e.placeId,
    'Valoración Google': e.rating,
    'Nº reseñas': e.resenas,
    'Distancia (km)': e.distanciaKm,
    'Fuente': 'Google Maps',
    'Fecha de captación': hoy,
    'Estado': 'Pendiente',
    'Notas': `[Auto] Encontrada buscando "${e.keyword}" en ${e.zona}`,
  };
  for (const k of Object.keys(fields)) if (fields[k] === null || fields[k] === undefined || fields[k] === '') delete fields[k];
  return { json: { fields } };
});
